#!/usr/bin/env python3
"""
Snow Tether — chess and battleship on one clock, no floor.
==========================================================
Closed meetings are chess pieces. They do not unhappen.
Unmeasured axes are battleship fog. HOLD until a shot lands.
0,0 is the last tether for that firm / period / axis.

Not a sensor. Not a SNARK. Not a floor under the web.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from enum import Enum
from typing import Iterable


class Outcome(str, Enum):
    GRANT = "GRANT"
    REFUSE = "REFUSE"
    HOLD = "HOLD"


REQUIRED = (
    "restore_verified",
    "kev_edge_checked",
    "admin_mfa",
    "payee_bound_offchannel",
)


def _now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


@dataclass(frozen=True)
class Tether:
    """One frozen contact. Immutable after landing."""

    firm_id: str
    period: str
    axis: str
    outcome: Outcome
    interior: int | None
    claimed: int | None
    landed: str

    @property
    def delta(self) -> int | None:
        if self.interior is None or self.claimed is None:
            return None
        return self.interior - self.claimed

    @property
    def key(self) -> tuple[str, str, str]:
        return (self.firm_id, self.period, self.axis)


class AlreadyLanded(Exception):
    """Shot on a square that already has a piece. History does not unhappen."""


class DualGame:
    """
    Chess layer: tethers[] — pieces already placed.
    Battleship layer: fog — cells not yet called.
    No baseline, no CPU floor, no 'normal week'.
    """

    def __init__(self, firm_id: str, period: str, axes: Iterable[str] = REQUIRED) -> None:
        if not firm_id or not period:
            raise ValueError("firm and period are the tether names")
        self.firm_id = firm_id
        self.period = period
        self.axes = tuple(axes)
        self._tethers: dict[str, Tether] = {}

    # -- battleship: fire once ------------------------------------------------

    def fire(
        self,
        axis: str,
        *,
        interior: int | None,
        claimed: int | None,
    ) -> Tether:
        """
        Call one cell. Unmeasured interior → HOLD (no piece, still fog).
        Measured short → REFUSE piece.
        Measured non-negative → GRANT piece.
        A second shot at the same axis is refused: the meeting already closed.
        """
        if axis not in self.axes:
            raise ValueError(f"unknown axis {axis!r}")
        if axis in self._tethers:
            raise AlreadyLanded(f"{axis} already closed for {self.firm_id} {self.period}")

        if interior is None or claimed is None:
            # Fog remains. HOLD is not a tether.
            return Tether(
                self.firm_id, self.period, axis, Outcome.HOLD, interior, claimed, _now()
            )

        delta = interior - claimed
        outcome = Outcome.GRANT if delta >= 0 else Outcome.REFUSE
        piece = Tether(
            self.firm_id, self.period, axis, outcome, interior, claimed, _now()
        )
        self._tethers[axis] = piece
        return piece

    # -- chess: glance only ---------------------------------------------------

    def glance(self, axis: str) -> Tether | None:
        """Read a placed piece. Does not re-check whether it still happened."""
        return self._tethers.get(axis)

    def fog(self) -> tuple[str, ...]:
        return tuple(a for a in self.axes if a not in self._tethers)

    def pieces(self) -> tuple[Tether, ...]:
        return tuple(self._tethers[a] for a in self.axes if a in self._tethers)

    @property
    def origin(self) -> Tether | None:
        """0,0 — last closed meeting on this board, not a floor."""
        landed = self.pieces()
        if not landed:
            return None
        return max(landed, key=lambda t: t.landed)

    # -- both games: one verdict ----------------------------------------------

    def verdict(self) -> Outcome:
        """
        HOLD if any required cell is still fog.
        REFUSE if any piece is REFUSE.
        GRANT only when every axis is a GRANT piece.
        """
        if self.fog():
            return Outcome.HOLD
        if any(t.outcome is Outcome.REFUSE for t in self.pieces()):
            return Outcome.REFUSE
        return Outcome.GRANT

    def same_meeting(self, other: DualGame) -> bool:
        return self.firm_id == other.firm_id and self.period == other.period

