#import "TesseraKernelBridge.h"
#include "TesseraKernel.hpp"

@implementation TesseraKernelBridge {
    tessera::Kernel _kernel;
}

- (void)setSampleRate:(double)sampleRate { _kernel.setSampleRate(sampleRate); }
- (void)reset { _kernel.reset(); }
- (void)setRatioIndex:(float)index { _kernel.setParameter(tessera::Param::RatioIndex, index); }
- (void)setPressure:(float)pressure { _kernel.setParameter(tessera::Param::Pressure, pressure); }
- (void)setVelocity:(float)velocity { _kernel.setParameter(tessera::Param::Velocity, velocity); }
- (float)ratioIndex { return _kernel.getParameter(tessera::Param::RatioIndex); }
- (float)pressure   { return _kernel.getParameter(tessera::Param::Pressure); }
- (float)velocity   { return _kernel.getParameter(tessera::Param::Velocity); }

- (void)processOutput:(float *)out frames:(uint32_t)frames {
    _kernel.process(nullptr, out, frames);
}

@end

