// Tiny ObjC++ façade so Swift can own AUAudioUnit while C++ owns samples.
// Do not put this header's methods on the render thread except process.

#pragma once

#import <Foundation/Foundation.h>

NS_ASSUME_NONNULL_BEGIN

@interface TesseraKernelBridge : NSObject

- (void)setSampleRate:(double)sampleRate;
- (void)reset;
- (void)setRatioIndex:(float)index;   // 0..5
- (void)setPressure:(float)pressure;  // 0..1
- (void)setVelocity:(float)velocity;  // EMA magnitude
- (float)ratioIndex;
- (float)pressure;
- (float)velocity;
- (void)processOutput:(float *)out frames:(uint32_t)frames;

@end

NS_ASSUME_NONNULL_END
